#include "settings_screen.h"
#include <assert.h>
#include <stdio.h>
#include <string.h>
typedef struct { size_t begun,rows,footers,ended; int fail_second_row; } fake_renderer;
static int begin(void *ctx,const rtp_screen_page *p){fake_renderer *f=ctx;f->begun++;assert(p->row_count==2);return 0;}
static int row(void *ctx,const rtp_screen_row *r,size_t i,size_t n){fake_renderer *f=ctx;(void)n;f->rows++;if(i==0)assert(!strcmp(r->title,"FTP Server"));if(i==1&&f->fail_second_row)return -1;return 0;}
static int footer(void *ctx,const char *l,const char *r){fake_renderer *f=ctx;f->footers++;assert(!strcmp(l,"Select")&&!strcmp(r,"Back"));return 0;}
static int end(void *ctx){((fake_renderer*)ctx)->ended++;return 0;}
int main(void){rtp_preferences p;rtp_preferences_ui ui;rtp_metadata_catalogue m;rtp_metadata_descriptor d;rtp_screen_page page;rtp_screen_renderer renderer={begin,row,footer,end};fake_renderer f={0};rtp_preferences_init(&p);rtp_metadata_init(&m);rtp_preferences_ui_init(&ui);assert(rtp_preferences_register(&p,"connectivity","",RTP_ENTRY_CATEGORY,1,10)==RTP_PREFS_OK);assert(rtp_preferences_register(&p,"ftp-service","connectivity",RTP_ENTRY_SETTING,1,10)==RTP_PREFS_OK);assert(rtp_preferences_register(&p,"usb-streaming","connectivity",RTP_ENTRY_SETTING,1,20)==RTP_PREFS_OK);memset(&d,0,sizeof(d));d.entry_id="connectivity";d.title="Connectivity";d.description="Network and connection services.";d.module_id="core";d.icon_key="network";assert(rtp_metadata_register(&m,&p,&d)==RTP_META_OK);d.entry_id="ftp-service";d.title="FTP Server";d.description="Manage the FTP service.";d.category_id="connectivity";d.module_id="connectivity";assert(rtp_metadata_register(&m,&p,&d)==RTP_META_OK);d.entry_id="usb-streaming";d.title="USB Streaming";d.description="Manage supported USB streaming.";assert(rtp_metadata_register(&m,&p,&d)==RTP_META_OK);assert(rtp_settings_screen_build(&ui,&p,&m,&page)==RTP_SCREEN_OK);assert(!strcmp(page.title,"Rt:Settings Extended")&&page.row_count==1&&!strcmp(page.rows[0].title,"Connectivity"));assert(rtp_preferences_ui_enter(&ui,&p,"connectivity")==RTP_UI_OK);snprintf(ui.frames[ui.depth-1].selected_id,sizeof(ui.frames[ui.depth-1].selected_id),"removed-entry");assert(rtp_settings_screen_build(&ui,&p,&m,&page)==RTP_SCREEN_OK);assert(page.row_count==2&&!strcmp(page.title,"Connectivity")&&page.rows[0].selected&&page.selected_index==0);assert(rtp_settings_screen_render(&page,&renderer,&f)==RTP_SCREEN_OK);assert(f.begun==1&&f.rows==2&&f.footers==1&&f.ended==1);f.fail_second_row=1;assert(rtp_settings_screen_render(&page,&renderer,&f)==RTP_SCREEN_RENDER_ERROR);assert(f.ended==2&&f.footers==1);puts("Settings screen adapter tests passed.");return 0;}
